 39→      const data = await fetchMemories();
 40→      setEntries(data.entries);
 41→      setRawContent(data.raw);
 42→    } catch {
 43→      // silently ignore
 44→    }
 45→  }, []);
 46→
 47→  useEffect(() => { loadMemories(); }, [loadMemories, refreshKey]);
 48→
 49→  useEffect(() => {
 50→    const handler = () => loadMemories();
 51→    window.addEventListener('memories-updated', handler);
 52→    return () => window.removeEventListener('memories-updated', handler);
 53→  }, [loadMemories]);
 54→
 55→  const handleDelete = async (content: string) => {
