 73→    return entries.filter((e) => e.content.toLowerCase().includes(q));
 74→  }, [entries, searchTerm]);
 75→
 76→  const grouped = CATEGORY_ORDER
 77→    .map((cat) => ({ category: cat, items: filteredEntries.filter((e) => e.category === cat) }));
 78→
 79→  return (
 80→    <div className="memories-panel">
 81→      <div className="memories-panel__actions">
 82→        <button
 83→          className="memories-panel__action-btn"
