120→                <li key={`${group.category}-${idx}`} className="memories-panel__item">
121→                  <span className="memories-panel__text">{entry.content}</span>
122→                  <button
123→                    className="memories-panel__delete-btn"
124→                    onClick={() => handleDelete(entry.content)}
125→                    title={t('deleteMemory')}
126→                  >
127→                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
128→                  </button>
129→                </li>
130→              ))}
131→            </ul>
132→          )}
133→        </div>
134→      ))}
135→
136→      {showFileModal && createPortal(
137→        <div className="skill-detail-overlay" onClick={() => setShowFileModal(false)}>
138→          <div className="skill-detail-modal" onClick={(e) => e.stopPropagation()}>
139→            <div className="skill-detail-modal__header">
140→              <span className="skill-detail-modal__name">{t('memoryFileTitle')}</span>
141→              <button className="skill-detail-modal__close" onClick={() => setShowFileModal(false)}>
142→                &times;
143→              </button>
144→            </div>
145→            <div className="skill-detail-modal__tabs">
146→              <button
147→                className={`skill-detail-modal__tab${detailTab === 'preview' ? ' skill-detail-modal__tab--active' : ''}`}
148→                onClick={() => setDetailTab('preview')}
149→              >
150→                {t('memoryPreview')}
151→              </button>
152→              <button
153→                className={`skill-detail-modal__tab${detailTab === 'source' ? ' skill-detail-modal__tab--active' : ''}`}
154→                onClick={() => setDetailTab('source')}
