183→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
184→  const { t } = useTranslation();
185→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
186→  const [isEditing, setIsEditing] = useState(false);
187→  const [editText, setEditText] = useState(message.content);
188→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
189→  const textareaRef = useRef<HTMLTextAreaElement>(null);
190→
191→  const isUser = message.role === 'user';
192→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
193→
194→  useEffect(() => {
195→    if (isEditing && textareaRef.current) {
196→      textareaRef.current.focus();
197→      textareaRef.current.selectionStart = textareaRef.current.value.length;
198→    }
199→  }, [isEditing]);
200→
201→  const handleEdit = () => {
202→    setEditText(message.content);
203→    setIsEditing(true);
204→    setIsConfirmingDelete(false);
205→  };
206→
207→  const handleCancelEdit = () => {
208→    setIsEditing(false);
209→    setEditText(message.content);
210→  };
211→
212→  const handleSaveEdit = () => {
213→    const trimmed = editText.trim();
214→    if (!trimmed || trimmed === message.content) {
215→      handleCancelEdit();
216→      return;
217→    }
218→    setIsEditing(false);
219→    editMessage(messageIndex, trimmed);
220→  };
221→
222→  const handleDeleteConfirm = () => {
223→    setIsConfirmingDelete(false);
224→    deleteMessage(messageIndex);
225→  };
226→
227→  const handleKeyDown = (e: React.KeyboardEvent) => {
228→    if (e.key === 'Escape') {
229→      handleCancelEdit();
230→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
231→      e.preventDefault();
232→      handleSaveEdit();
233→    }
234→  };
235→
236→  let streamingRemainder: string | undefined;
237→  if (hasSegments && message.isStreaming && message.content) {
238→    const segmentedText = message.segments!
239→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
240→      .map((s) => s.text || '')
241→      .join('');
242→    const remaining = message.content.slice(segmentedText.length);
243→    if (remaining.trim()) {
244→      streamingRemainder = remaining;
245→    }
246→  }
247→
248→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
249→  const isInAnswerPhase = message.currentPhase === 'answer';
250→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
251→
252→  const hasCharts = hasSegments && message.segments!.some(
253→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
254→  );
255→
256→  const answerBlockSegments = hasSegments
257→    ? message.segments!
258→        .filter((s) =>
259→          (s.type === 'answer' && s.text?.trim()) ||
260→          (s.type === 'subagent_end' && !s.chart_spec && !s.sqlResults?.length && s.text?.trim() && !hasAnswer) ||
261→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
262→          (s.type === 'subagent_end' && s.chart_spec)
263→        )
264→        .map((s) => {
265→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
266→            return { ...s, text: stripChartSpecBlocks(s.text) };
267→          }
268→          return s;
269→        })
270→        .filter((s) => {
271→          // Remove text segments that became empty after stripping chart blocks
272→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
273→            return false;
274→          }
275→          return true;
276→        })
277→    : [];
278→
279→  const questionSegments = hasSegments
280→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
281→    : [];
282→
283→  return (
284→    <div className={`message-bubble message-bubble--${message.role}`}>
285→      <div className="message-bubble__header">
286→        {isUser ? t('you') : t('assistant')}
287→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
288→          <span className="message-bubble__actions">
289→            <button
290→              className="message-bubble__action-btn"
291→              onClick={handleEdit}
292→              title={t('editMessage')}
293→            >
294→              &#9998;
295→            </button>
296→            <button
297→              className="message-bubble__action-btn message-bubble__action-btn--delete"
298→              onClick={() => setIsConfirmingDelete(true)}
299→              title={t('deleteMessage')}
300→            >
301→              &#128465;
302→            </button>
303→          </span>
304→        )}
305→      </div>
306→
307→      {isUser && isConfirmingDelete && (
308→        <div className="message-bubble__confirm-delete">
309→          <span>{t('deleteConfirm')}</span>
310→          <div className="message-bubble__confirm-actions">
311→            <button
312→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
313→              onClick={handleDeleteConfirm}
314→            >
315→              {t('delete')}
316→            </button>
317→            <button
318→              className="message-bubble__confirm-btn"
319→              onClick={() => setIsConfirmingDelete(false)}
320→            >
321→              {t('cancel')}
322→            </button>
323→          </div>
324→        </div>
325→      )}
326→
327→      {isUser && isEditing ? (
328→        <div className="message-bubble__edit-mode">
329→          <textarea
330→            ref={textareaRef}
331→            className="message-bubble__edit-textarea"
332→            value={editText}
333→            onChange={(e) => setEditText(e.target.value)}
334→            onKeyDown={handleKeyDown}
335→            rows={3}
336→          />
337→          <div className="message-bubble__edit-actions">
338→            <button
339→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
340→              onClick={handleSaveEdit}
341→            >
342→              {t('saveResend')}
343→            </button>
344→            <button
345→              className="message-bubble__edit-btn"
346→              onClick={handleCancelEdit}
347→            >
348→              {t('cancel')}
349→            </button>
350→          </div>
351→        </div>
352→      ) : hasSegments ? (
353→        <div className="message-bubble__segments">
354→          {!questionSegments.some((s) => !s.userAnswer) && (
355→            <ThinkingBlock
356→              segments={message.segments!}
357→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
358→              isThinkingPhase={isThinkingPhase}
359→              isAgentStreaming={!!message.isStreaming}
360→              hasAnswer={hasAnswer}
361→            />
362→          )}
363→          {questionSegments.map((seg, i) => (
364→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
365→              <UserQuestion
366→                questionData={seg.questionData!}
367→                userAnswer={seg.userAnswer}
368→                userFreeText={seg.userFreeText}
369→                answerDurationMs={seg.answerDurationMs}
370→              />
371→            </div>
372→          ))}
373→          {answerBlockSegments.length > 0 && (
374→            <div className="message-bubble__segment message-bubble__segment--answer">
375→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
376→              {answerBlockSegments.map((seg, i) => {
377→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
378→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
379→                  return (
380→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
381→                      {seg.type === 'tool' && seg.toolResult ? (
382→                        <InlineQueryResult result={seg.toolResult!} />
383→                      ) : seg.chart_spec ? (
384→                        seg.chart_spec.library === 'vegalite' && seg.chart_spec.spec
385→                          ? <VegaLiteChartWidget spec={seg.chart_spec.spec} />
386→                          : <ChartWidget data={seg.chart_spec.data ?? []} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
387→                      ) : null}
388→                    </div>
389→                  );
390→                }
391→                // Text segment (answer or subagent_end without chart_spec)
392→                return (
393→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
394→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(seg.text!)}</ReactMarkdown>
395→                  </div>
396→                );
397→              })}
398→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
399→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
400→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
401→                return displayText?.trim() ? (
402→                  <div className="message-bubble__segment-content">
403→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(displayText)}</ReactMarkdown>
404→                  </div>
405→                ) : null;
406→              })()}
407→              {!message.isStreaming && message.durationMs != null && (
408→                <div className="message-bubble__duration">
409→                  {t('answeredIn', { time: formatDuration(message.durationMs) })}
410→                </div>
411→              )}
412→            </div>
413→          )}
414→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
415→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
416→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
417→            return displayText?.trim() ? (
418→              <div className="message-bubble__segment message-bubble__segment--answer">
419→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
420→                <div className="message-bubble__segment-content">
421→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(displayText)}</ReactMarkdown>
422→                </div>
423→              </div>
424→            ) : null;
425→          })()}
426→          {message.segments!.filter((s) => s.type === 'error').map((seg, i) => {
427→            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
428→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
429→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
430→          })}
431→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
432→            <span className="message-bubble__typing">{t('thinking')}</span>
433→          )}
434→        </div>
435→      ) : (
436→        <>
437→          <div className="message-bubble__content">
438→            {message.content ? (
439→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(message.content)}</ReactMarkdown>
440→            ) : message.isStreaming ? (
441→              <span className="message-bubble__typing">{t('thinking')}</span>
442→            ) : null}
443→          </div>
444→          {message.toolCalls && message.toolCalls.length > 0 && (
445→            <div className="message-bubble__tools">
446→              {message.toolCalls.map((tc) => (
447→                <InlineQueryResult key={tc.toolCallId} result={tc} />
448→              ))}
449→            </div>
450→          )}
451→        </>
452→      )}
453→    </div>
454→  );
455→}
