352→            }
353→            state.segments.push({ type: 'error', errorMessage: error });
354→            const durationMs = Date.now() - state.startTime;
355→            updateMessages(msgs =>
356→              msgs.map(m =>
357→                m.id === assistantId
358→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...state.segments], durationMs }
359→                  : m
360→              )
