 99→export async function runAgentLoop(
100→  message: string,
101→  agentSessionId: string | null,
102→  langfuseSessionId: string | null,
103→  conversationHistory: { role: string; content: string }[] | null,
104→  conversationId?: string | null,
105→  callbacks?: AgentCallbacks,
106→  signal?: AbortSignal,
107→  userSessionId?: string,
108→  skills?: string[],
109→  chartLibrary?: string,
110→): Promise<void> {
111→  if (!callbacks) return;
112→  try {
113→    const response = await fetch('/api/chat', {
114→      method: 'POST',
115→      headers: {
116→        'Content-Type': 'application/json',
117→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
118→      },
119→      body: JSON.stringify({
120→        message,
121→        session_id: agentSessionId,
122→        conversation_id: conversationId,
123→        langfuse_session_id: langfuseSessionId,
124→        conversation_history: conversationHistory ?? [],
125→        ...(skills?.length ? { skills } : {}),
126→        chart_library: chartLibrary || 'plotly',
127→      }),
128→      signal,
129→    });
130→
131→    if (!response.ok) {
132→      const errorText = await response.text();
133→      callbacks.onError(`Server error: ${errorText}`);
134→      return;
135→    }
136→
137→    await streamSSE(response, callbacks, signal);
138→  } catch (e: unknown) {
139→    if (signal?.aborted) return;
140→    const msg = e instanceof Error ? e.message : 'Connection failed';
141→    callbacks.onError(msg);
142→  }
143→}
