398→      const convId = activeConversationIdRef.current;
399→
400→      // If this conversation has an active stream, abort it first
401→      let existingMessages: ChatMessage[] | null = null;
402→      if (convId && streamStatesRef.current.has(convId)) {
403→        const existingState = streamStatesRef.current.get(convId)!;
404→        existingMessages = existingState.messages;
405→        existingState.abortController.abort();
406→        if (existingState.flushTimer) {
407→          clearTimeout(existingState.flushTimer);
408→        }
409→        streamStatesRef.current.delete(convId);
410→        setStreamingConversationIds(prev => {
411→          const next = new Set(prev);
412→          if (convId) next.delete(convId);
413→          return next;
414→        });
415→      }
416→
417→      // Truncate messages at the edit point in the backend
418→      if (convId) {
419→        try {
420→          await fetch(`/api/conversations/${convId}/messages?from_sort_order=${messageIndex}`, {
421→            method: 'DELETE',
422→          });
423→        } catch {
424→          // Best-effort
425→        }
426→        messagesCacheRef.current.delete(convId);
427→      }
428→
429→      // Build conversation history from messages before the edit point
430→      const currentMsgs = existingMessages || messagesRef.current;
431→      const conversationHistory: { role: string; content: string }[] = [];
432→      for (let i = 0; i < messageIndex; i++) {
433→        const msg = currentMsgs[i];
434→        if (msg.role === 'user' || msg.role === 'assistant') {
435→          conversationHistory.push({ role: msg.role, content: msg.content });
436→        }
437→      }
438→
439→      const controller = new AbortController();
