451→        toolCalls: [],
452→        isStreaming: true,
453→      };
454→
455→      const truncatedMessages = currentMsgs.slice(0, messageIndex);
456→      const streamMessages = [...truncatedMessages, userMsg, assistantMsg];
457→
458→      // Create per-conversation stream state
459→      const state: StreamState = {
460→        assistantId,
461→        segments: [],
462→        currentText: '',
463→        textBuffer: '',
464→        phase: 'thinking',
