715→  const deleteMessage = useCallback(
716→    (messageIndex: number) => {
717→      const convId = activeConversationIdRef.current;
718→      // Only block if this specific conversation is streaming
719→      if (convId && streamStatesRef.current.has(convId)) return;
720→
721→      // Store remaining messages as history for Langfuse context on next send
722→      setMessages((prev) => {
723→        const remaining = prev.slice(0, messageIndex);
724→        pendingHistoryRef.current = remaining
725→          .filter((m) => m.role === 'user' || m.role === 'assistant')
726→          .map((m) => ({ role: m.role, content: m.content }));
727→        return remaining;
728→      });
729→
730→      // Persist the truncation to the backend
731→      if (convId) {
732→        fetch(`/api/conversations/${convId}/messages?from_sort_order=${messageIndex}`, {
733→          method: 'DELETE',
734→        }).catch(() => {
735→          // Best-effort: if this fails the UI is already updated
736→        });
737→        // Invalidate cache so switching back loads from backend
738→        messagesCacheRef.current.delete(convId);
739→      }
740→
741→      // Clear session so next message starts fresh
742→      sessionIdRef.current = null;
743→    },
744→    []
745→  );
